def cyclic_deps(tree: PackageDAG) -> list[list[DistPackage | ReqPackage]]:
    """
    Return cyclic dependencies as list of lists.

    :param  tree: package tree/dag
    :returns: list of lists representing cyclic dependencies
    """
    # Build a graph representation for easier traversal
    graph = {}
    for p, rs in tree.items():
        if p.key not in graph:
            graph[p.key] = {"node": p, "deps": []}
        for r in rs:
            graph[p.key]["deps"].append(r)
            if r.key not in graph:
                graph[r.key] = {"node": None, "deps": []}
            # Get the actual DistPackage for this requirement
            dist_pkg = tree.get_node_as_parent(r.key)
            if dist_pkg:
                graph[r.key]["node"] = dist_pkg

    # Find all cycles in the graph
    all_cycles = []

    # For each package, check if it's part of a cycle
    for p, rs in tree.items():
        for r in rs:
            # Check if there's a path from r back to p
            if r.key in graph and graph[r.key]["node"] is not None:
                # Start a DFS from r to find a path back to p
                visited = set()
                path = []

                def dfs(current_key: str, target_key: str, path_so_far: list[DistPackage | ReqPackage]) -> bool:
                    if current_key == target_key and path_so_far:  # Found a path back to the target
                        path.extend(path_so_far)
                        return True

                    if current_key in visited:  # Already visited this node
                        return False

                    visited.add(current_key)

                    # Get the node and its dependencies
                    node_info = graph.get(current_key)
                    if not node_info or node_info["node"] is None:
                        return False

                    # Try each dependency
                    for dep in node_info["deps"]:
                        new_path = path_so_far + [node_info["node"], dep]
                        if dfs(dep.key, target_key, new_path):
                            return True

                    return False

                # Start DFS from r to find a path back to p
                if dfs(r.key, p.key, [p, r]):
                    # We found a cycle, add it to the list if it's not already there
                    # For compatibility with tests, we need to extract just the keys
                    cycle_keys = [node.key for node in path]

                    # Check if this cycle is already in all_cycles
                    if not any(cycle_keys == [node.key for node in existing_cycle] for existing_cycle in all_cycles):
                        all_cycles.append(path)

    return all_cycles
